// ============================================================
//   Alarm Aggregator (LIVE)
// ------------------------------------------------------------
//   Collects incoming alarm values in flow.alarm_snapshot.
//   On real value change: immediate force-flush.
//   Identical values go out on the next heartbeat only.
// ============================================================

let path = msg.path;
if (!path) {
    node.warn("Alarm Aggregator: msg.path missing");
    return null;
}

let val = msg.payload;
if (val === null || val === undefined) return null;

let snapshot = flow.get("alarm_snapshot") || {};
let lastSent = flow.get("alarm_last_sent") || {};

snapshot[path] = val;
flow.set("alarm_snapshot", snapshot);

let previous = lastSent[path];
if (previous !== val) {
    node.status({
        fill: val > 0 ? "red" : "green",
        shape: "dot",
        text: `FLUSH ${path}: ${previous} → ${val}`
    });
    return { payload: "force_flush", trigger: "change" };
}

node.status({
    fill: "grey",
    shape: "dot",
    text: `${path}=${val} (no change)`
});
return null;

// ============================================================
//   Alarm Emit (LIVE)
// ------------------------------------------------------------
//   Builds multi-value payload from flow.alarm_snapshot and
//   sends it to the existing victron-virtual node.
// ============================================================

let snapshot = flow.get("alarm_snapshot") || {};

if (Object.keys(snapshot).length === 0) {
    node.status({ fill: "grey", shape: "ring", text: "snapshot empty" });
    return null;
}

let payload = Object.assign({}, snapshot);
flow.set("alarm_last_sent", Object.assign({}, snapshot));

let trigger = msg.trigger || "unknown";
let activeCount = Object.values(payload).filter(v => v > 0).length;
let totalCount = Object.keys(payload).length;

node.status({
    fill: activeCount > 0 ? "red" : "green",
    shape: "dot",
    text: `${trigger} | ${activeCount}/${totalCount} active | ${new Date().toLocaleTimeString()}`
});

return { payload: payload };

