// ============================================================
//   Current Sum
// ------------------------------------------------------------
//   Sums the currents of all 3 shunts.
//   Writes the result to flow.virt_current and sends
//   a message with msg.path = '/Dc/0/Current' to the
//   aggregator.
// ============================================================

if (!msg.topic) {
    node.warn("No topic set!");
    return null;
}

let current = context.get("current") || {};
current[msg.topic] = Number(msg.payload);
context.set("current", current);

// calculate sum
let sum = 0;
for (let key in current) {
    if (!isNaN(current[key])) {
        sum += current[key];
    }
}

// round to 1 decimal place
sum = Math.round(sum * 10) / 10;

// in flow context for power calculation
flow.set("virt_current", sum);

node.status({
    fill: "green",
    shape: "dot",
    text: `Σ = ${sum.toFixed(1)} A`
});

return { payload: sum };

// ============================================================
//   Voltage Logic
// ------------------------------------------------------------
//   Selects from 3 shunt voltages based on voltage level:
//     • ≥ 51.7 V  → highest voltage (MAX)
//                   Normal operation & end-of-charge:
//                   protects weakest string from overcharge
//     • < 51.7 V  → lowest voltage (MIN)
//                   Deep discharge range (lower LiFePO4 knee):
//                   protects weakest string from deep discharge
//
//   Threshold 51.7 V = 16 × 3.23 V/cell = lower plateau knee
//   Normal operation (54.4–55.2 V) is always in the MAX branch.
//
//   Rate limiter: max 0.03 V/cycle at threshold crossing
//   prevents voltage jumps that cause ESS regulation jitter.
//
//   Status shows mode | voltage (x/3 active shunts)
// ============================================================

let volt = context.get("volt") || {};
volt[msg.topic] = Number(msg.payload);
context.set("volt", volt);

let values = Object.values(volt).filter(v => !isNaN(v));
if (values.length === 0) return null;

const THRESHOLD_V = 51.7;
const MAX_V_STEP  = 0.03;

const avg = values.reduce((a,b)=>a+b,0) / values.length;
const targetVoltage = (avg < THRESHOLD_V)
    ? Math.min(...values)
    : Math.max(...values);
let mode = (avg < THRESHOLD_V) ? "low MIN ↓" : "high MAX ↑";

const prevVoltage = context.get('vLast') || targetVoltage;
const delta = targetVoltage - prevVoltage;
let voltage = (Math.abs(delta) > MAX_V_STEP)
    ? prevVoltage + Math.sign(delta) * MAX_V_STEP
    : targetVoltage;
context.set('vLast', voltage);

voltage = Math.round((voltage + 0.00) * 100) / 100;
flow.set("virt_voltage", voltage);
flow.set("virt_voltage_ts", Date.now());

node.status({
    fill: "green", shape: "dot",
    text: `${mode} | ${voltage.toFixed(2)} V (${values.length}/3)`
});

return { payload: voltage };

// ============================================================
//   Power Calc
// ------------------------------------------------------------
//   Reads virt_voltage and virt_current from flow context,
//   multiplies them to power and sends with
//   msg.path = '/Dc/0/Power' to the aggregator.
// ============================================================

let voltage = flow.get("virt_voltage");
let current = flow.get("virt_current");

if (voltage === undefined || current === undefined) {
    node.status({ fill: "grey", shape: "ring", text: "waiting for V & I" });
    return null;
}

let power = Math.round(voltage * current);

node.status({
    fill: "green",
    shape: "dot",
    text: `${power} W`
});

return { payload: power };

// ============================================================
//   Battery Main Aggregator (LIVE)
// ------------------------------------------------------------
//   Collects /Dc/0/Current, /Dc/0/Voltage, /Dc/0/Power in
//   flow.main_snapshot.
//   On exceeding the per-path deadband: immediate flush.
//   Otherwise identical/small changes go out on the
//   next heartbeat only.
// ============================================================

const DEADBAND = {
    "/Dc/0/Current":  0.1,    // A
    "/Dc/0/Voltage":  0.01,   // V
    "/Dc/0/Power":    5       // W
};

let path = msg.path;
if (!path) {
    node.warn("Main Aggregator: msg.path missing");
    return null;
}

let val = msg.payload;
if (val === null || val === undefined) return null;

let snapshot = flow.get("main_snapshot") || {};
let lastSent = flow.get("main_last_sent") || {};

snapshot[path] = val;
flow.set("main_snapshot", snapshot);

let previous = lastSent[path];
let threshold = DEADBAND[path] !== undefined ? DEADBAND[path] : 0;

let diff = (previous === undefined) ? Infinity : Math.abs(val - previous);

if (diff >= threshold) {
    node.status({
        fill: "yellow",
        shape: "dot",
        text: `FLUSH ${path}: ${previous} → ${val} (Δ${diff.toFixed(2)})`
    });
    return { payload: "force_flush", trigger: "change" };
}

node.status({
    fill: "grey",
    shape: "dot",
    text: `${path}=${val} (Δ${diff.toFixed(2)} < ${threshold})`
});
return null;

// ============================================================
//   Battery Main Emit
// ------------------------------------------------------------
//   Builds multi-value payload from flow.main_snapshot and
//   sends it to the existing victron-virtual node.
// ============================================================

let snapshot = flow.get("main_snapshot") || {};

if (Object.keys(snapshot).length === 0) {
    node.status({ fill: "grey", shape: "ring", text: "snapshot empty" });
    return null;
}

let payload = Object.assign({}, snapshot);
flow.set("main_last_sent", Object.assign({}, snapshot));

let trigger = msg.trigger || "unknown";
let i = snapshot["/Dc/0/Current"];
let u = snapshot["/Dc/0/Voltage"];
let p = snapshot["/Dc/0/Power"];

let statusText = `${trigger} | `;
if (u !== undefined) statusText += `${u.toFixed(2)}V `;
if (i !== undefined) statusText += `${i.toFixed(1)}A `;
if (p !== undefined) statusText += `${p}W`;

node.status({
    fill: "green",
    shape: "dot",
    text: statusText.trim()
});

return { payload: payload };

// ============================================================
//   SOC Average (Soft-Min on discharge)
// ------------------------------------------------------------
//   Collects SOC values of all 3 shunts with timestamp.
//   Values older than 60 s are ignored (stale detection).
//
//   Mode-dependent output:
//     • Discharging (I < -5 A) → Avg - Spread/2  (Soft-Min)
//     • Charging    (I >  5 A) → Avg
//     • Idle    (|I| ≤ 5 A) → Avg
//
//   Soft-Min:
//   At small spread nearly identical to Avg. At large
//   spread the output becomes more conservative and approaches
//   Min. Self-regulating, no manual intervention
//   at the Cerbo limit required.
//
//   Status shows Mode + output SOC + Avg + Spread:
//     • green  at Spread ≤ 5 %
//     • yellow at Spread >  5 %  (strings drifting apart)
//
//   Sends msg.path = '/Soc' to the aggregator.
// ============================================================

const BATTERIES = [
    "com.victronenergy.battery/288",
    "com.victronenergy.battery/274",
    "com.victronenergy.battery/290"
];
const STALE_MS          = 600000; // 600 s Stale-Filter
const CURRENT_THRESHOLD = 5;     // A Deadzone für Mode-Detection
const SPREAD_WARN       = 5;     // % SOC Spread → Status gelb

if (!BATTERIES.includes(msg.service)) {
    return null;
}

let soc = context.get("soc") || {};
let now = Date.now();

soc[msg.service] = {
    value: Number(msg.payload),
    time:  now
};
context.set("soc", soc);

// --- collect valid (non-stale) values ------------------------
let values = [];
let activeShunts = 0;
for (let id of BATTERIES) {
    if (soc[id] && (now - soc[id].time) < STALE_MS) {
        values.push(soc[id].value);
        activeShunts++;
    }
}

if (values.length === 0) {
    node.status({ fill: "grey", shape: "ring", text: "no valid shunts" });
    return null;
}

// --- Statistics ---------------------------------------------
const minSoc = Math.min(...values);
const maxSoc = Math.max(...values);
const avgSoc = values.reduce((a, b) => a + b, 0) / values.length;
const spread = maxSoc - minSoc;

// --- Mode determination based on current --------------------
const currentI = flow.get("virt_current");
let socOut;
let mode;

if (typeof currentI === "number" && currentI < -CURRENT_THRESHOLD) {
    // Discharging → Soft-Min (Avg minus half spread)
    socOut = avgSoc - (spread / 2);
    mode   = "discharge ↓";
} else if (typeof currentI === "number" && currentI > CURRENT_THRESHOLD) {
    // Charging → Avg
    socOut = avgSoc;
    mode   = "charge ↑";
} else {
    // Idle (or current not yet known) → Avg
    socOut = avgSoc;
    mode   = (typeof currentI === "number") ? "idle ø" : "init ø";
}

socOut = Math.round(socOut * 10) / 10;

// --- Diagnostic values in flow context for inspection -------
flow.set("soc_min",    Math.round(minSoc * 10) / 10);
flow.set("soc_max",    Math.round(maxSoc * 10) / 10);
flow.set("soc_avg",    Math.round(avgSoc * 10) / 10);
flow.set("soc_spread", Math.round(spread * 10) / 10);
flow.set("soc_out",    socOut);
flow.set("soc_mode",   mode);

// --- Status display ------------------------------------------
const statusColor = spread > SPREAD_WARN ? "yellow" : "green";
node.status({
    fill:  statusColor,
    shape: "dot",
    text:  `${mode} ${socOut.toFixed(1)}% ` +
           `(avg ${avgSoc.toFixed(1)}, Δ${spread.toFixed(1)}, ${activeShunts}/3)`
});

msg.payload = socOut;
return msg;

// ============================================================
//   SOC Aggregator (LIVE)
// ------------------------------------------------------------
//   Collects the averaged SOC in flow.soc_snapshot.
//   On change >= deadband: immediate force-flush.
//   Otherwise heartbeat every 60 s.
// ============================================================

const DEADBAND = 0.1; // % SOC

let path = msg.path;
if (!path) {
    node.warn("SOC Aggregator: msg.path missing");
    return null;
}

let val = msg.payload;
if (val === null || val === undefined) return null;

let snapshot = flow.get("soc_snapshot") || {};
let lastSent = flow.get("soc_last_sent") || {};

snapshot[path] = val;
flow.set("soc_snapshot", snapshot);

let previous = lastSent[path];
let diff = (previous === undefined) ? Infinity : Math.abs(val - previous);

if (diff >= DEADBAND) {
    node.status({
        fill: "yellow",
        shape: "dot",
        text: `FLUSH ${previous} → ${val} (Δ${diff.toFixed(2)})`
    });
    return { payload: "force_flush", trigger: "change" };
}

node.status({
    fill: "grey",
    shape: "dot",
    text: `SOC=${val} (Δ${diff.toFixed(2)} < ${DEADBAND})`
});
return null;

// ============================================================
//   SOC Emit
// ------------------------------------------------------------
//   Builds multi-value payload from flow.soc_snapshot and
//   sends it to the existing victron-virtual node.
// ============================================================

let snapshot = flow.get("soc_snapshot") || {};

if (Object.keys(snapshot).length === 0) {
    node.status({ fill: "grey", shape: "ring", text: "snapshot empty" });
    return null;
}

let payload = Object.assign({}, snapshot);
flow.set("soc_last_sent", Object.assign({}, snapshot));

let trigger = msg.trigger || "unknown";
let soc = snapshot["/Soc"];

node.status({
    fill: "green",
    shape: "dot",
    text: `${trigger} | ${soc !== undefined ? soc.toFixed(1) + ' %' : '-'}`
});

return { payload: payload };
